# 도메인 시리얼라이저 계약

Prisma 레코드를 API 응답 객체로 변환하는 순수 함수들. 라우트 핸들러가
직접 객체 리터럴을 조립하지 않고 반드시 이 함수를 거친다. 필드 누락·오타로
인한 hurl 실패를 한 곳에서 막기 위한 장치다.

**위치**: `src/serializers/` (파일 분할: `user.ts`, `profile.ts`,
`article.ts`, `comment.ts`), 배럴은 `src/serializers/index.ts`.

## 공통 타입

```ts
// src/types.ts
export type ProfileDto = {
  username: string;
  bio: string | null;
  image: string | null;
  following: boolean;
};

/** 인증된 사용자 id, 익명이면 null. optional-auth 라우트에서 사용. */
export type ViewerId = number | null;
```

## 시그니처

```ts
// src/serializers/user.ts
export function toUserResponse(
  user: { email: string; username: string; bio: string | null; image: string | null },
  token: string,
): { user: { email: string; token: string; username: string; bio: string | null; image: string | null } };

// src/serializers/profile.ts
export function toProfile(
  user: { username: string; bio: string | null; image: string | null },
  following: boolean,
): ProfileDto;

export function toProfileResponse(profile: ProfileDto): { profile: ProfileDto };

// src/serializers/article.ts
/** Prisma에서 include로 가져온 글 레코드. 태스크 08이 이 타입을 정의하고 export한다. */
export type ArticleWithRelations = {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { username: string; bio: string | null; image: string | null };
  tags: { order: number; tag: { name: string } }[];
  _count: { favorites: number };
  /** viewer가 좋아요했으면 길이 1, 아니면 0. 익명이면 빈 배열. */
  favorites: unknown[];
  /** viewer가 저자를 팔로우하면 길이 1. 익명이면 빈 배열. */
  authorFollowedBy: unknown[];
};

export type ArticleDto = {
  slug: string; title: string; description: string; body: string;
  tagList: string[]; createdAt: string; updatedAt: string;
  favorited: boolean; favoritesCount: number; author: ProfileDto;
};

export function toArticle(a: ArticleWithRelations): ArticleDto;

/** ArticleDto에서 body 키를 제거한 객체. 목록 응답 전용. */
export function toArticleSummary(a: ArticleWithRelations): Omit<ArticleDto, 'body'>;

